<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';requireAdmin();requireSuperAdmin();
header('Cache-Control: no-store, private');header('X-Robots-Tag: noindex, nofollow');
require_once __DIR__.'/../includes/public-site/Journal.php';require_once __DIR__.'/../includes/public-site/Metrics.php';require_once __DIR__.'/../includes/public-site/helpers.php';
$db=getDB();$editor=new \StratEdgePublic\Journal($db);$error='';$ready=false;$current=null;
try{$editor->install();$ready=true;}catch(Throwable $e){error_log('[public-journal] storage unavailable');$error='Le stockage du journal est indisponible. Aucun article n’a été modifié.';}
$id=is_string($_GET['id']??null)?$_GET['id']:'';
if($ready&&$id!==''){try{$current=$editor->get($id,true);if(!$current)$error='Publication introuvable.';}catch(Throwable $e){$error='Publication inaccessible.';}}
$fields=$current['data']??['title'=>'','slug'=>'','summary'=>'','body'=>'','sources'=>'','author'=>'La rédaction StratEdge','kind'=>'guide','sport'=>'football','decision'=>'observation','match_label'=>'','market'=>'','odds'=>'','odds_at'=>'','kickoff_at'=>'','result'=>'en_attente','score'=>''];
$publishLocal=$current?(new DateTimeImmutable($current['publish_at']))->setTimezone(new DateTimeZone('Europe/Paris'))->format('Y-m-d\TH:i'):'';
$status=$current['status']??'draft';$expected=(int)($current['version']??0);
if($_SERVER['REQUEST_METHOD']==='POST'&&$ready){
 try{
  if(!is_string($_POST['csrf']??null)||!verifyCsrf($_POST['csrf']))throw new InvalidArgumentException('Session expirée. Rechargez la page avant d’enregistrer.');
  if(($_POST['action']??'')==='lab_draft'){
   require_once __DIR__.'/football-lab/lib/Store.php';require_once __DIR__.'/../includes/public-site/LabDraft.php';
   $store=new \StratEdgeLab\Store($db);$run=$store->get(is_string($_POST['run']??null)?$_POST['run']:'',(int)($_SESSION['membre_id']??0));
   if($run['kind']!=='analysis')throw new InvalidArgumentException('Analyse introuvable.');$match=null;
   foreach($run['data']['analysis']['matches']??[] as $candidate)if(($candidate['key']??null)===($_POST['match']??null)){$match=$candidate;break;}
   if(!$match)throw new InvalidArgumentException('Match introuvable dans votre analyse.');
   $saved=$editor->save(\StratEdgePublic\LabDraft::make($match,$run['data']['analysis']));
  }else{
   $fields=\StratEdgePublic\Journal::validate($_POST);$postedId=is_string($_POST['id']??null)&&$_POST['id']!==''?$_POST['id']:null;
   $old=$postedId?$editor->get($postedId,true):null;$expected=(int)($_POST['version']??0);
   $status=is_string($_POST['status']??null)?$_POST['status']:'draft';$publishLocal=is_string($_POST['publish_at']??null)?$_POST['publish_at']:'';
   $date=$publishLocal===''?null:DateTimeImmutable::createFromFormat('!Y-m-d\TH:i',$publishLocal,new DateTimeZone('Europe/Paris'));
   if($publishLocal!==''&&(!$date||$date->format('Y-m-d\TH:i')!==$publishLocal))throw new InvalidArgumentException('Date de publication invalide.');
   $publish=$date?$date->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d\TH:i:s\Z'):null;
   // Preserve seconds on an already public record; the UI edits datetime-local to minute precision.
   if($old&&$old['status']==='published'&&$old['publish_at']<=\StratEdgePublic\Journal::now())$publish=$old['publish_at'];
   $saved=$editor->save($fields,$postedId,$expected,$status,$publish,is_string($_POST['reason']??null)?$_POST['reason']:'');
  }
  header('Location: /panel-x9k3m/journal.php?id='.rawurlencode($saved).'&saved=1');exit;
 }catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(PDOException $e){$error='Enregistrement impossible. Vérifiez que l’adresse de l’article n’est pas déjà utilisée, puis réessayez.';error_log('[public-journal] save failed');}catch(Throwable $e){$error='Enregistrement impossible ou modification simultanée. Rechargez la publication avant de réessayer.';error_log('[public-journal] operation failed');}
}
if($current&&isset($_GET['preview'])){
 $post=$current;$revisions=$editor->revisions($post['id']);$frontPreview=true;$frontNoIndex=true;$frontMember=true;$frontSource='direct';$pageActive='article';$pageTitle='Aperçu privé — '.$post['data']['title'];$pageDescription=$post['data']['summary'];$pagePath='/article.php?slug='.rawurlencode($post['slug']);
 require __DIR__.'/../includes/public-site/views/article.php';exit;
}
$all=[];$metrics=[];$sales=[];
if($ready){try{$all=$editor->recent(true,200);$metrics=\StratEdgePublic\Metrics::report($db);}catch(Throwable $e){$error=$error?:'Le tableau de publication ne peut pas être chargé.';}}
// Read-only totals. These are separate ledgers, not source-attributed conversions or net revenue.
foreach(['Abonnements Stripe validés'=>"SELECT COUNT(*) AS n, COALESCE(SUM(montant_eur),0) AS total FROM stripe_payments WHERE statut='validé' AND date_paiement>=DATE_SUB(NOW(),INTERVAL 15 DAY)",'Packs de crédits enregistrés'=>"SELECT COUNT(*) AS n, COALESCE(SUM(prix_paye),0) AS total FROM credits_paris WHERE date_achat>=DATE_SUB(NOW(),INTERVAL 15 DAY)"] as $label=>$sql){try{$sales[$label]=$db->query($sql)->fetch(PDO::FETCH_ASSOC);}catch(Throwable $e){$sales[$label]=null;}}
$pageActive='journal';$public=$current&&$current['status']==='published'&&$current['publish_at']<=\StratEdgePublic\Journal::now();
$shareUrl=$public?'https://stratedgepronos.fr'.front_article_url($current):'';
?>
