<section class="editor-panel"><div class="editor-panel-head"><h2>Votre calendrier éditorial</h2><span><?= count($all) ?> publication(s), jusqu’aux 200 plus récentes</span></div><?php if(!$all): ?><p class="editor-muted">Votre premier article commence ci-dessous.</p><?php endif; ?><div class="editor-list"><?php foreach($all as $row):$state=$row['status']==='draft'?'Brouillon':($row['publish_at']>\StratEdgePublic\Journal::now()?'Programmé':'Publié'); ?><a href="?id=<?= front_h($row['id']) ?>#edition" class="editor-item"><span class="editor-state <?= $state==='Publié'?'published':'' ?>"><?= $state ?></span><div><strong><?= front_h($row['data']['title']) ?></strong><small><?= front_h(front_kind($row['data']['kind'])) ?> · <?= front_date($row['publish_at'],true) ?> Paris · v<?= (int)$row['version'] ?></small></div><span aria-hidden="true">↗</span></a><?php endforeach; ?></div></section>
<section class="editor-panel" id="edition"><div class="editor-panel-head"><h2><?= $current?'Modifier la publication':'Écrire un article' ?></h2><?php if($current): ?><a href="?id=<?= front_h($current['id']) ?>&preview=1" target="_blank" rel="noopener">Aperçu privé ↗</a><?php endif; ?></div><?php if($ready): ?><form method="post" class="editor-form"><input type="hidden" name="csrf" value="<?= front_h(csrfToken()) ?>"><input type="hidden" name="id" value="<?= front_h($current['id']??'') ?>"><input type="hidden" name="version" value="<?= $expected ?>"><label>Titre<input required name="title" maxlength="150" value="<?= front_h($fields['title']) ?>" data-slug-from="article-slug"></label><div class="editor-columns"><label>Adresse de l’article<input id="article-slug" required name="slug" maxlength="180" pattern="[a-z0-9]+(-[a-z0-9]+)*" value="<?= front_h($fields['slug']) ?>" <?= $public?'readonly':'' ?>><small>Lettres minuscules, chiffres et tirets.</small></label><label>Signature<input name="author" maxlength="100" value="<?= front_h($fields['author']) ?>"></label></div><div class="editor-columns"><label>Rubrique<select name="kind"><?php foreach(['guide'=>'Guide','analyse'=>'Analyse','debrief'=>'Débrief','coulisses'=>'Coulisses'] as $v=>$l): ?><option value="<?= $v ?>" <?= $fields['kind']===$v?'selected':'' ?>><?= $l ?></option><?php endforeach; ?></select></label><label>Sport<select name="sport"><?php foreach(['football'=>'Football','tennis'=>'Tennis','multisports'=>'Multisports'] as $v=>$l): ?><option value="<?= $v ?>" <?= $fields['sport']===$v?'selected':'' ?>><?= $l ?></option><?php endforeach; ?></select></label></div><label>Résumé pour la page et le partage<textarea name="summary" rows="3" maxlength="400" required><?= front_h($fields['summary']) ?></textarea></label><label>Texte de l’article<textarea name="body" rows="18" required><?= front_h($fields['body']) ?></textarea><small>Texte simple. Une ligne commençant par « ## » forme un intertitre. Séparez les paragraphes par une ligne vide. Le HTML n’est pas interprété.</small></label><label>Sources — une adresse HTTPS par ligne<textarea name="sources" rows="4" placeholder="https://…"><?= front_h($fields['sources']) ?></textarea><small>Obligatoires pour publier une analyse. Précisez dans le texte la date de consultation et les incertitudes.</small></label><details class="editor-details" <?= $fields['match_label']!==''?'open':'' ?>><summary>Dossier de match et suivi de la décision</summary><div class="editor-fields"><label>Affiche<input name="match_label" maxlength="180" value="<?= front_h($fields['match_label']) ?>" <?= $public?'readonly':'' ?>></label><label>Décision<select name="decision"><?php foreach(['observation'=>'Présélection descriptive seulement','retenu'=>'Pari retenu après analyse','ecarte'=>'Pari examiné puis écarté'] as $v=>$l): ?><option value="<?= $v ?>" <?= $fields['decision']===$v?'selected':'' ?>><?= $l ?></option><?php endforeach; ?></select></label><div class="editor-columns"><label>Marché<input name="market" maxlength="180" value="<?= front_h($fields['market']) ?>" <?= $public?'readonly':'' ?>></label><label>Cote relevée<input name="odds" inputmode="decimal" maxlength="12" value="<?= front_h($fields['odds']) ?>" <?= $public?'readonly':'' ?>></label></div><div class="editor-columns"><label>Relevé de la cote · Paris<input name="odds_at" type="datetime-local" value="<?= front_h($fields['odds_at']) ?>" <?= $public?'readonly':'' ?>></label><label>Coup d’envoi · Paris<input name="kickoff_at" type="datetime-local" value="<?= front_h($fields['kickoff_at']) ?>" <?= $public?'readonly':'' ?>></label></div><div class="editor-columns"><label>Résultat<select name="result"><?php foreach(['en_attente'=>'À renseigner','gagne'=>'Gagné','perdu'=>'Perdu','annule'=>'Annulé'] as $v=>$l): ?><option value="<?= $v ?>" <?= $fields['result']===$v?'selected':'' ?>><?= $l ?></option><?php endforeach; ?></select></label><label>Score final<input name="score" maxlength="20" value="<?= front_h($fields['score']) ?>"></label></div><p class="editor-muted">Le pari et sa cote sont figés une fois publics. Une nouvelle sélection ne peut pas être publiée après le coup d’envoi. Le résultat est ajouté ensuite avec un motif de mise à jour.</p></div></details><div class="editor-columns"><label>État<select name="status"><?php if(!$public): ?><option value="draft" <?= $status==='draft'?'selected':'' ?>>Brouillon privé</option><?php endif; ?><option value="published" <?= $status==='published'?'selected':'' ?>><?= $public?'Publié':'Publier / programmer' ?></option></select></label><label>Publication · heure de Paris<input type="datetime-local" name="publish_at" value="<?= front_h($publishLocal) ?>" <?= $public?'readonly':'' ?>><small>Vide = maintenant. Une date future programme l’apparition publique.</small></label></div><label>Motif de mise à jour <?= $public?'(obligatoire)':'' ?><input name="reason" maxlength="500" <?= $public?'required minlength="8"':'' ?> placeholder="Exemple : résultat ajouté après le coup de sifflet final."></label><div class="editor-actions"><button class="editor-button" type="submit">Enregistrer la publication</button><?php if($public): ?><a href="<?= front_h($shareUrl) ?>" target="_blank" rel="noopener">Lire la version publique ↗</a><?php endif; ?></div></form><?php endif; ?></section>
